from src.database.config import supabase
import bcrypt

def hash_pass(password):
    return bcrypt.hashpw(password.encode( ), bcrypt.gensalt()).decode()
  #this function takes a password as input and returns the hashed version of the password using bcrypt. The password is first encoded to bytes, then hashed with a salt(random hash value) generated by bcrypt, and finally decoded back to a string for storage in the database.  

def check_pass(password, hashed):
    return bcrypt.checkpw(password.encode(), hashed.encode())
  #this function takes a password and a hashed password as input and checks if the password matches the hashed password using bcrypt. The password is first encoded to bytes, then compared with the hashed password using bcrypt's checkpw function, which returns True if they match and False otherwise.
 
def check_teacher_exists(username):
    response = supabase.table("teachers").select("username").eq("username",username).execute()

    return len(response.data) > 0
    # basically we are selecting the username from the teachers table and checking if it exists in the database. If it does, we return True, otherwise we return False

def create_teacher(username,password,name):
    data = {"username":username,
            "password": hash_pass(password),
            "name":name}
    response = supabase.table("teachers").insert(data).execute()


def teacher_login(username,password):
    response = supabase.table("teachers").select("*").eq("username",username).execute()
    # check if username exists


    #if exists then response.data will be a list of dictionaries containing the teacher's information. If it doesn't exist, response.data will be an empty list.
    if response.data: 
      teacher = response.data[0]
      # from the list of dictionaries, we take the first dictionary
      if check_pass(password, teacher["password"]):
        return teacher
    return None


def get_all_students():
   response = supabase.table("students").select("*").execute()
