def create_student(name , face_embedding=None , voice_embedding=None):
  data = {'name' : name , 'face_embedding':face_embedding , 'voice_embedding':voice_embedding}
  response = supabase.table("students").insert(data).execute()
  return response.data


def create_subject(subject_code,name,section,teacher_id):
   data = {'subject_code':subject_code,'name':name,'section':section,'teacher_id':teacher_id}

   response = supabase.table("subjects").insert(data).execute()

   return response.data


# Fetch teacher's subjects, count enrolled students and unique attendance sessions, remove nested data, and return the processed subjects.
def get_teacher_subjects(teacher_id):
  response = supabase.table("subjects").select("*, subject_students(count),attendance_log(timestamp)").eq('teacher_id',teacher_id).execute()

  subjects = response.data

  for sub in subjects:
      sub['total_students'] = sub.get("subject_students",[{}])[0].get('count',0) if sub.get('subject_students') else 0 
      # if sub.get() is returning something then fetch [0] first elem count value else 0 ,[{}] default field will be returned by sub.get

      # sample subject data 
      """
      subjects =[
      {
        "id": 1,
        "name": "DBMS",
        "teacher_id": 10,
        "subject_students": [{"count": 45}],
        "attendance_logs": [
            {"timestamp": "2026-10-16T09:00:00"}
        ]
        },
      ]
      """

      attendance = sub.get("attendance_log",[])

      unique_sessions = len(set(log['timestamp'] for log in attendance))

      sub['total_classes'] = unique_sessions

      sub.pop('subject_student',None)
      sub.pop('attendance_log',None)

  return subjects

def enroll_student_to_subject(student_id,subject_id):
   data = {'subject_id':subject_id,'student_id':student_id}
   response = supabase.table('subject_students').insert(data).execute()

   return response.data


def unenroll_student_to_subject(student_id,subject_id):
   response = supabase.table('subject_students').delete().eq('student_id',student_id).eq('subject_id',subject_id).execute()

   return response.data

def get_student_subjects(student_id):
  response = supabase.table("subject_students").select("* , subjects(*)").eq('student_id',student_id).execute()
  # fetch student id and subject id from subject_students table and then fetch all subjects rows from subject table whose subject id is mapped with subject_student table
  return response.data

def get_student_attendance(student_id):
   response = supabase.table("attendance_log").select("* , subjects(*)").eq('student_id',student_id).execute()

   return response.data

def create_attendance(logs):
    response = supabase.table('attendance_log').insert(logs).execute()
    return response.data

def get_attendance_for_teacher(teacher_id):
  res = supabase.table("attendance_log").select("* , subjects!inner(*),students!inner(*)").eq('subjects.teacher_id',teacher_id).execute()
  #attendace_log doesnt have teacherid so we r doing inner join of subject and attendace table on subject id and then fetching records
  
  return res.data
